#!/usr/bin/env python3
"""Writes MethylPhys_CPG_SOP_v4.md, the operating procedure for chain v4, from the chain's own files (2026-10-18, OTH-074):
CANON/commissioning.json (what is commissioned, for what), chain/FROZEN_INPUTS_v4.json (every frozen file and its checksum),
chain/chain_sequence.json (the live stages), and the IAM-A shape reference (the cell types IAM-A can be declared for).
Nothing in the generated file is typed twice. --check refuses drift. Run by CANON/checkpoint.sh."""
import json, os, sys
HERE = os.path.dirname(os.path.abspath(__file__)); MP = os.path.dirname(HERE); ROOT = os.path.dirname(os.path.dirname(MP)); CH = os.path.join(MP, "chain")
OUT = os.path.join(HERE, "MethylPhys_CPG_SOP_v4.md")
J = lambda p: json.load(open(p, encoding="utf-8"))
def text():
    K = J(os.path.join(ROOT, "CANON", "commissioning.json"))["instruments"]; F = J(os.path.join(CH, "FROZEN_INPUTS_v4.json"))["files"]
    S = J(os.path.join(CH, "chain_sequence.json")); SH = sorted(J(os.path.join(CH, "Runtime Matrices", "IAM_A_SelfRef", "shape_reference_v1.json"))["cells"])
    rel = lambda p: os.path.relpath(os.path.join(ROOT, p), HERE).replace(os.sep, "/")
    L = ["# MethylPhys CPG SOP: chain v4", "",
         "Generated by `build_sop_v4.py` from the chain's own files. Do not edit by hand. Where this document and the code differ, the code is what runs.", "",
         "**The chain's job:** one sample goes in; every commissioned instrument reads it inside its commissioned scope, reads outside it with a plain note "
         "saying it has not yet been tested there, or declines with its reason. Research use only; not a diagnostic test.", "",
         "## 1. What is commissioned", "", "| Instrument and scope | Commissioned | Note |", "|---|---|---|"]
    L += [f"| {i['name']} | {i['date']} | [{os.path.basename(i['note'])}]({rel(i['note'])}) |" for i in K]
    L += ["", "Each was commissioned by a test sealed before its data were read. A reading outside these scopes is printed with the note "
          "\"reading shown; not yet tested with ... on ...\" and is not a commissioned result.", "",
          "## 2. Install", "", "From a fresh clone of the repository, Python 3.11:", "", "```",
          "git clone https://github.com/hmahaffeyges/IAM-Validation.git && cd IAM-Validation/Biological_Physics/MethylPhys/chain",
          "python3 -m venv .venv && . .venv/bin/activate && pip install -r requirements.txt", "```", "",
          "Stage 1 needs the Illumina manifest; methylprep downloads it on first use into `$HOME/.methylprep_manifest_files/`. "
          "Without it the run stops with `ENVIRONMENT_MISSING_MANIFEST` (exit 3) and the array is not judged.", "",
          "## 3. Check the chain (one command)", "", "```", "python3 release_check_v4.py", "```", "",
          "It runs every check of the chain, including real arrays from the chain's test data, planted samples for each instrument, and the checksum of every "
          "frozen file below. Every check must pass; a run that does not pass is not a commissioned chain.", "",
          "## 4. Read one sample", "", "Arrays (a raw IDAT pair, Illumina EPIC v1):", "", "```", "cd MethylPhys_Interface",
          "python3 run_sample.py --grn S_Grn.idat --red S_Red.idat --specimen \"whole blood\" --id S001 --out S001.html",
          "```", "", "Isolated neutrophils: `--specimen \"isolated neutrophils\"`. Optional: `--sex F|M`, `--age`, recorded when given. "
          "Same-run healthy references for the median tare: `--slide-ref-table refs.csv` (column `A`).", "",
          "Sequencing (whole-genome bisulfite), against the sample's own reference:", "", "```",
          "python3 run_sample.py --pat S.pat.gz --seq-cell \"cd8 t cells\" --id S002 --out S002.html",
          "python3 run_sample.py --bam S.bam --ref-fasta hg19.fa --assembly hg19 --seq-cell \"cd8 t cells\" --id S003 --out S003.html", "```", "",
          f"`--seq-cell` names the cell type; the sample-shape check has a healthy shape for {len(SH)} cell types: " + ", ".join(SH) + ".", "",
          "## 5. What the chain declines, and why", "",
          "- An EPIC v2 or 450K array: refused at intake with one sentence (no frozen Met-A reference for that platform).",
          "- A failed array (Stage 0 quarantine): exit 2, no report.",
          "- A sequencing sample whose shape is outside the healthy shape of its declared cell type, or with too few qualifying molecules: IAM-A declines and says why.",
          "- A noisy array (the noise gate): the Met-A state is withheld and no gauge is drawn.", "",
          "## 6. Outputs", "",
          "- `S001.html`: the report. At a glance; cell shares (IAM-Deconvolver against IAM-Atlas v2.1); Met-A; the C-score with its HEALPix sky plate; IAM-A; the technical record.",
          "- `S001_bundle.json`: every stage's output, with the chain's commit.", "- one row appended to `evidence_ledger.jsonl` beside the report.", "",
          "## 7. Stages in the live path", "", f"{len(S['live_path'])} steps, in order (from `chain/chain_sequence.json`):", "", "| Step | Code |", "|---|---|"]
    L += [f"| {x['step']} | `{x['where']}` |" for x in S["live_path"]]
    L += ["", "## 8. Frozen inputs", "", "Every reference the chain reads is a committed file; nothing is fitted at run time. The release check verifies each checksum.", "",
          "| File (in `chain/`) | SHA-256 |", "|---|---|"]
    L += [f"| `{k}` | `{v[:16]}…` |" for k, v in sorted(F.items())]
    L += ["", "## 9. Rules", "",
          "- Synthetic first: every new test runs on planted data, read by the chain's exact rule, before any real data is opened.",
          "- Sealed before read: a test's samples, rule and bars are committed before its data is downloaded; it is scored once.",
          "- Clean clone: every chain change passes `release_check_v4.py` on a fresh clone, on a clean machine, before it is called tested.",
          "- One reading per instrument; no lines beyond Normal are printed until they are measured on the gauge.", "",
          "The earlier procedure, for chain v3, is kept as the record of how the chain was built: [MethylPhys_CPG_SOP_v3.md](MethylPhys_CPG_SOP_v3.md).", ""]
    return "\n".join(L)
if __name__ == "__main__":
    t = text()
    if "--check" in sys.argv:
        ok = os.path.exists(OUT) and open(OUT, encoding="utf-8").read() == t
        print("build_sop_v4: " + ("ok" if ok else "REFUSED: MethylPhys_CPG_SOP_v4.md differs from the chain's files (run python3 Biological_Physics/MethylPhys/sop/build_sop_v4.py)")); sys.exit(0 if ok else 1)
    open(OUT, "w", encoding="utf-8").write(t); print("build_sop_v4: written", len(t.splitlines()), "lines")
